return await challenge.record([
{kind:"companion",lines:[1],says:"The new description limits the kept fare to long crossings and has short-crossing passengers pay the difference, but the story's summary still promises the original fare whenever a passenger moves to a dearer sailing. The suggested summary change matches it to the new scope.",evidence:[{id:"jira:SYN-45",quote:"Rebooking: keep the original fare when moving to a dearer sailing"},{line:1,quote:"On the short crossings they pay the difference."}],changes:[1]},
{kind:"conflict",lines:[1],says:"The current description gives the operations policy as never charging the difference. The rewrite changes that policy to charge it on short crossings, and nothing in the ticket records operations changing its mind. The receipt line 'Fare difference waived' is still unconditional, and no acceptance criterion covers charging on a short crossing.",evidence:[{id:"jira:SYN-45",quote:"We absorb the difference; we never charge it."},{line:1,quote:"- The receipt says 'Fare difference waived'"}]},
{kind:"related",lines:[1],says:"SYN-26, outside the workstream, gives passengers on an at-risk sailing a free change. Charging short-crossing passengers the fare difference may need to line up with that promise.",evidence:[{id:"jira:SYN-26",quote:"Passengers on an at-risk sailing get a heads-up and a free change."}]}
]);

